; replay.asm — LFSR-16 AND-cascade XOR renderer (ZX Spectrum)
;
; Reads seeds binary table (generated by gen_seeds_bin.py).
; Usage:
;   python3 gen_seeds_bin.py seeds.json seeds_lfsr.bin
;   mza replay.asm -o replay.bin
;   mze --target spectrum replay.bin
;
; Binary table format (placed at SEEDS):
;   u16 LE : n_seeds
;   × n_seeds: [seed u16 LE][ox u8][oy u8][blk u8][and_n u8][warmup u8]

    ORG $8000

BUF     EQU $C000       ; 768-byte block buffer
SEEDS   EQU $CC00       ; seeds binary table

; ── Entry ──────────────────────────────────────────────────────
start:
    ; Clear screen
    ld  hl, $4000
    ld  de, $4001
    ld  bc, $17FF
    ld  (hl), 0
    ldir

    ; BC = n_seeds (u16 LE at SEEDS)
    ld  hl, SEEDS
    ld  c, (hl)
    inc hl
    ld  b, (hl)
    inc hl          ; HL = pointer to first entry

    ; BC = 0? nothing to do
    ld  a, b
    or  c
    ret z

seed_loop:
    push bc         ; save remaining count
    push hl         ; save entry pointer

    ; Load entry: [seed u16][ox][oy][blk][and_n][warmup]
    ld  e, (hl)     ; seed_lo
    inc hl
    ld  d, (hl)     ; seed_hi  → DE = seed
    inc hl
    ld  a, (hl)     ; ox
    ld  (var_ox), a
    inc hl
    ld  a, (hl)     ; oy
    ld  (var_oy), a
    inc hl
    ld  a, (hl)     ; blk
    ld  (var_blk), a
    inc hl
    ld  a, (hl)     ; and_n
    ld  (var_and_n), a
    inc hl
    ld  b, (hl)     ; warmup → B

    call make_buf   ; DE=seed, B=warmup, (var_and_n)=and_n → fills BUF
    call apply_buf  ; (var_ox,var_oy,var_blk) → XOR onto screen

    pop hl
    ld  de, 7
    add hl, de      ; advance to next entry
    pop bc
    dec bc
    ld  a, b
    or  c
    jr  nz, seed_loop

    ret

; ── make_buf: fill BUF[768] ────────────────────────────────────
; In:  DE = seed (0 → use 1), B = warmup
; Mem: (var_and_n) = and_n
; Out: BUF[0..767] filled (0 or 1)
; Clobbers: AF, BC, DE, HL
make_buf:
    ld  a, d
    or  e
    jr  nz, .seed_ok
    ld  de, 1       ; seed=0 → use 1
.seed_ok:
    ; warmup: run lfsr16 B times
    ld  a, b
    or  a
    jr  z, .after_warmup
.warmup_loop:
    call lfsr16
    djnz .warmup_loop
.after_warmup:
    ; generate 768 blocks
    ld  hl, BUF
    ld  bc, 768     ; counter
.buf_loop:
    ; acc = AND of and_n LFSR bits
    ld  a, (var_and_n)
    ld  b, a        ; B = and_n
    ld  a, 1        ; acc = 1
.and_loop:
    push af         ; save acc
    call lfsr16     ; DE = next state
    ld  a, e
    and 1           ; bit = LSB
    pop  hl2        ; pop to scratch... actually:
    ; We need to save acc across lfsr16 call.
    ; Strategy: use IXL as acc accumulator
    ; (avoids stack push/pop inside tight loop)
    jr  .and_loop_ok  ; re-implement cleanly:

    ; Restart make_buf with cleaner loop:
    ; (above draft replaced by clean version below)
    ret

; ── make_buf (clean) ───────────────────────────────────────────
; Same interface as above.
make_buf:
    ld  a, d
    or  e
    jr  nz, .snz
    inc de
.snz:
    ; warmup
    ld  a, b
    or  a
    jr  z, .wu_done
.wu:
    call lfsr16
    djnz .wu
.wu_done:
    ld  iy, BUF     ; IY = buffer pointer
    ld  bc, 768     ; 768 blocks
.blk:
    ; and_n iterations: acc (IYH) = AND of and_n LFSR LSBs
    ld  a, (var_and_n)
    ld  iyh, a      ; use IYH as counter (clobbered but OK — reload each iteration)
    ld  iyl, 1      ; acc = 1
.and_it:
    call lfsr16
    ld  a, e
    and 1
    and iyl         ; acc &= bit
    ld  iyl, a
    dec iyh
    jr  nz, .and_it
    ld  (iy+0), iyl ; buf[i] = acc
    inc iy
    dec bc
    ld  a, b
    or  c
    jr  nz, .blk
    ret

; ── lfsr16: DE = (DE>>1) ^ (B400 if DE&1 else 0) ─────────────
; In/Out: DE = LFSR state
; Clobbers: A, F
lfsr16:
    ld  a, e
    srl d
    rr  e           ; DE >>= 1, old LSB → carry
    ret nc          ; LSB was 0: no XOR
    ld  a, d
    xor $B4
    ld  d, a        ; D ^= 0xB4
    ld  a, e
    xor $00
    ld  e, a        ; E ^= 0x00 (nop, but explicit)
    ret

; ── apply_buf: XOR BUF blocks onto screen ────────────────────
; Reads (var_ox, var_oy, var_blk)
; Clobbers: AF, BC, DE, HL, IX
apply_buf:
    ld  a, (var_blk)
    ld  (cur_blk), a

    ld  iy, BUF
    ld  d, 0        ; by = 0
.row:
    ld  e, 0        ; bx = 0
.col:
    ld  a, (iy+0)
    or  a
    jr  z, .skip_block

    ; pixel base: px = ox + bx*blk,  py = oy + by*blk
    ld  a, (var_blk)
    ld  b, a        ; B = blk
    ld  a, e        ; bx
    call mul8       ; A = bx*blk (blk≤8, bx≤31 → max 248, fits u8)
    ld  c, a
    ld  a, (var_ox)
    add a, c        ; px_base = ox + bx*blk
    ld  (px_base), a

    ld  a, (var_blk)
    ld  b, a
    ld  a, d        ; by
    call mul8       ; A = by*blk
    ld  c, a
    ld  a, (var_oy)
    add a, c        ; py_base = oy + by*blk
    ld  (py_base), a

    ; inner loop: dy in 0..blk-1, dx in 0..blk-1
    ld  a, (var_blk)
    ld  b, a        ; B = blk (dy counter)
    ld  a, 0
    ld  (cur_dy), a
.dy_loop:
    ld  a, (var_blk)
    ld  c, a        ; C = blk (dx counter)
    ld  a, 0
    ld  (cur_dx), a
.dx_loop:
    ld  a, (py_base)
    ld  hl, (cur_dy)
    add a, l        ; py = py_base + dy
    cp  96
    jr  nc, .skip_px
    ld  h, a        ; H = py

    ld  a, (px_base)
    ld  hl, (cur_dx)
    add a, l        ; px = px_base + dx
    cp  128
    jr  nc, .skip_px
    ld  l, a        ; L = px

    push bc
    push de
    push iy
    call xor_pixel  ; H=y, L=x
    pop  iy
    pop  de
    pop  bc

.skip_px:
    ld  a, (cur_dx)
    inc a
    ld  (cur_dx), a
    dec c
    jr  nz, .dx_loop

    ld  a, (cur_dy)
    inc a
    ld  (cur_dy), a
    dec b
    jr  nz, .dy_loop

.skip_block:
    inc iy
    inc e           ; bx++
    ld  a, e
    cp  32
    jr  nz, .col
    inc d           ; by++
    ld  a, d
    cp  24
    jr  nz, .row
    ret

; ── mul8: A = A * B (small: blk≤8, val≤31 → max 248) ────────
; Simple repeated addition
mul8:
    push bc
    ld  c, a
    xor a
    ld  (mul_cnt), a
.m:
    add a, c
    djnz .m
    pop bc
    ret

; ── xor_pixel: H=y (0..95), L=x (0..127) ────────────────────
; ZX Spectrum pixel address and bit XOR.
; Clobbers: AF, BC, HL
xor_pixel:
    ; Compute address: 0x4000 | (y>>6)<<11 | (y&7)<<8 | (y>>3&7)<<5 | (x>>3)
    ld  a, h        ; y
    ld  c, l        ; x

    ; Build high byte of address: $40 | (y&7) | (y>>6)<<3
    ld  b, a
    and $C0
    rlca
    rlca
    rlca            ; (y>>6) into bits 2:1:0, shifted to 4:3:2 range? let's be precise:
    ; y>>6 = 0..1 (only bit6), place into bits 4:3 of high byte
    ; Standard: high = $40 | (y>>6)<<3 | (y&7)
    ld  a, b        ; y
    and $C0         ; bits 7:6
    rlca            ; rotate: bit6 → bit7, bit7→bit0... not ideal.

    ; Clean implementation using the formula:
    ; addr = $4000 + (y&$C0)<<5 + (y&7)<<8 + (y>>3 & 7)<<5 + (x>>3)
    ; high = $40 | ((y&$C0)>>3) | (y&7)
    ; low  = (y>>3 & 7)<<5 | (x>>3)
    ld  a, b        ; y
    and $C0
    rrca
    rrca
    rrca            ; (y & $C0) >> 3
    or  $40         ; base $40xx
    ld  d, a
    ld  a, b        ; y
    and $07         ; y & 7
    or  d
    ld  d, a        ; D = high byte of address

    ld  a, b        ; y
    and $38         ; y & 0b00111000
    rlca
    rlca            ; (y>>3 & 7) << 5
    ld  e, a
    ld  a, c        ; x
    rrca
    rrca
    rrca
    and $1F         ; x >> 3
    or  e
    ld  e, a        ; E = low byte

    ; bit mask: 1 << (7 - (x & 7))
    ld  a, c
    and 7
    ld  b, a
    ld  a, $80
    or  a
    jr  z, .got_mask
.shr:
    rrca
    djnz .shr
.got_mask:
    ex  de, hl      ; HL = pixel address
    xor (hl)
    ld  (hl), a
    ret

; ── Variables ─────────────────────────────────────────────────
var_ox:   defb 0
var_oy:   defb 0
var_blk:  defb 4
var_and_n:defb 3
cur_blk:  defb 4
px_base:  defb 0
py_base:  defb 0
cur_dx:   defb 0
cur_dy:   defb 0
mul_cnt:  defb 0

; ── Seeds binary table ────────────────────────────────────────
; Assemble address must match SEEDS EQU above.
; Fill with output of gen_seeds_bin.py:
;   org $CC00
; seeds_table:
;   incbin "seeds_lfsr.bin"
